#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

static inline bool prefix(int n,int v,int left,int c,int i) {
    int pos;
    if(left) pos=c;
    else pos = n-v+c;
    if(pos>i) return false;
    int small = c+max(0,i-n+v-c);
    return small == i/2;
}

static inline bool works(int n,int v,int side,int c,int i) {
    if(prefix(n,v,side,c,i)) return true;
    int j=n-1-i;
    int yz = v-1-c;
    return prefix(n,v,1-side,yz,j);
}

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<int> a(n);
	    vector<vector<int>> where(n+1);
	    for(int i=0;i<n;i++) {
	        cin>>a[i];
	        where[a[i]].push_back(i);
	    }
	    if(n==1) {
	        cout<<(a[0] == 1 ? 1 : 0) << endl;
	        continue;
	    }
	    int force=-1;
	    bool imp = false;
	    for(int i:where[n]) {
	        if(i!=0 && i!=n-1) {
	            imp = true;
	            break;
	        }
	        int need = (i==0 ? 0 : n-1);
	        if(force == -1) force = need;
	        else if(force != need) imp = true;
	    }
	    if(imp) {
	        cout<<0<<endl;
	        continue;
	    }
	    vector<ll> dp(n,0), nxt(n,0);
	    dp[0] = 1;
	    for(int v=1;v<n;++v){
	        fill(nxt.begin(),nxt.end(),0);
	        for(int c=0;c<v;++c){
	            if(!dp[c]) continue;
	            for(int side=0;side<=1;++side){
	                bool ok = true;
	                for(int i:where[v]){
	                    if(!works(n,v,side,c,i)) {
	                        ok=false;
	                        break;
	                    }
	                }
	                if(ok) {
	                    int nc=c+side;
	                    nxt[nc] += dp[c];
	                    if(nxt[nc] >= MOD) nxt[nc] -= MOD;
	                }
	            }
	        }
	        dp.swap(nxt);
	    }
	    if(force != -1) cout<<dp[force] % MOD << endl;
	    else {
	        ll ans=0;
	        for(int c=0;c<n;++c) {
	            ans+= dp[c];
	            if(ans>=MOD) ans-= MOD;
	        }
	        cout<<ans<<endl;
	    }
	}
return 0;
}
